eStatus": "visual", "nameEvidence": "AI taxmini. Chizmadagi shakli va yig‘ilmadagi o‘rniga qarab taxmin qilindi; rasmiy pozitsiya jadvali topilmadi.", "nameSource": "", "needsReview": true}]'))
UPDATE catalogs SET data=(
 SELECT json_group_array(json(CASE WHEN EXISTS(SELECT 1 FROM updates u WHERE u.image=json_extract(m.value,'$.image')) THEN
  json_set(m.value,'$.parts',json((SELECT json_group_array(json(CASE WHEN u.id IS NOT NULL
   AND json_extract(p.value,'$.name')=u.oldName
   AND json_extract(p.value,'$.nameStatus')=u.oldStatus
   THEN json_set(p.value,'$.name',u.name,'$.nameStatus','visual','$.nameEvidence',u.nameEvidence,'$.nameSource',u.nameSource,'$.needsReview',json('true'))
   ELSE p.value END)) FROM json_each(m.value,'$.parts') p LEFT JOIN updates u ON u.image=json_extract(m.value,'$.image') AND u.id=json_extract(p.value,'$.id')))) ELSE m.value END)) FROM json_each(catalogs.data) m
),revision=revision+1 WHERE id='main' AND EXISTS(
 SELECT 1 FROM json_each(catalogs.data) m, json_each(m.value,'$.parts') p, updates u
 WHERE json_extract(m.value,'$.image')=u.image AND json_extract(p.value,'$.id')=u.id
 AND json_extract(p.value,'$.name')=u.oldName AND json_extract(p.value,'$.nameStatus')=u.oldStatus
);
